/* selectEnemyTeamList */
SELECT * FROM ( SELECT DISTINCT ON (monster_id_1, monster_id_2, monster_id_3) key, monster_id_1, monster_id_2, monster_id_3 , image_url1, image_url2, image_url3 , total_count, total_rate, win_count, lose_count , leader_id, leader_type, leader_stat, leader_increase_by, leader_icon, leader_skill_description FROM ( SELECT monster_id_1 || '-' || monster_id_2 || '-' || monster_id_3 AS key , monster_id_1, monster_id_2, monster_id_3 , image_url_1 AS image_url1, image_url_2 AS image_url2, image_url_3 AS image_url3 , total_count, total_rate, win_count, lose_count , leader_id, leader_type, leader_stat, leader_increase_by, leader_icon, leader_skill_desc AS leader_skill_description , 1 AS _deck_src FROM ( SELECT monster_id_1, monster_id_2, monster_id_3 , SUM(total_count) AS total_count , ROUND(100.0 * SUM(win_count) / NULLIF(SUM(total_count), 0), 1) AS total_rate , SUM(win_count) AS win_count, SUM(lose_count) AS lose_count , MAX(image_url_1) AS image_url_1, MAX(image_url_2) AS image_url_2, MAX(image_url_3) AS image_url_3 , MAX(leader_id) AS leader_id, MAX(leader_type) AS leader_type , MAX(leader_stat) AS leader_stat, MAX(leader_increase_by) AS leader_increase_by , MAX(leader_icon) AS leader_icon, MAX(leader_skill_desc) AS leader_skill_desc FROM siege_defense_deck_stats WHERE 1=1
AND guild_id = #{view_guild_id}::text
AND guild_id = #{sess_guild_id}::text
AND ( (SELECT COUNT(*) FROM guild_siege_season WHERE end_date IS NULL) = 0 OR season_yyyymm >= COALESCE( #{current_season_yyyymm}, (SELECT TO_CHAR(DATE_TRUNC('month', gss.start_date), 'YYYYMM') FROM guild_siege_season gss WHERE gss.end_date IS NULL ORDER BY gss.season_no DESC LIMIT 1), '000000' ) )
AND monster_id_1 IN #{id}
AND monster_id_2 IN #{id} AND monster_id_3 IN #{id}
AND (monster_id_2 IN #{id} OR monster_id_3 IN #{id})
AND (monster_id_2 IN #{id} OR monster_id_3 IN #{id})
GROUP BY monster_id_1, monster_id_2, monster_id_3
HAVING SUM(lose_count) >= #{min_lose_count}::int
) stats_deck UNION ALL SELECT d.monster_id_1 || '-' || d.monster_id_2 || '-' || d.monster_id_3 AS key , d.monster_id_1, d.monster_id_2, d.monster_id_3 , m1.image_url AS image_url1, m2.image_url AS image_url2, m3.image_url AS image_url3 , 0 AS total_count, 0 AS total_rate, 0 AS win_count, 0 AS lose_count , m1.leader_id AS leader_id, ml1.type AS leader_type, ml1.stat AS leader_stat , ml1.increase_by AS leader_increase_by, ml1.icon_path AS leader_icon , get_leader_skill_desc(ml1.type, ml1.stat, ml1.increase_by) AS leader_skill_description , 2 AS _deck_src FROM siege_defense_deck_manual d INNER JOIN monster m1 ON d.monster_id_1 = m1.monster_id INNER JOIN monster m2 ON d.monster_id_2 = m2.monster_id INNER JOIN monster m3 ON d.monster_id_3 = m3.monster_id LEFT JOIN monster_leaders ml1 ON m1.leader_id = ml1.leader_id WHERE 1=1
AND d.guild_id = #{view_guild_id}::text
AND d.guild_id = #{sess_guild_id}::text
AND ( (SELECT COUNT(*) FROM guild_siege_season WHERE end_date IS NULL) = 0 OR d.season_yyyymm >= COALESCE( #{current_season_yyyymm}, (SELECT TO_CHAR(DATE_TRUNC('month', gss.start_date), 'YYYYMM') FROM guild_siege_season gss WHERE gss.end_date IS NULL ORDER BY gss.season_no DESC LIMIT 1), '000000' ) )
AND d.monster_id_1 IN #{id}
AND d.monster_id_2 IN #{id} AND d.monster_id_3 IN #{id}
AND (d.monster_id_2 IN #{id} OR d.monster_id_3 IN #{id})
AND (d.monster_id_2 IN #{id} OR d.monster_id_3 IN #{id})
AND 1=0
AND NOT EXISTS ( SELECT 1 FROM siege_defense_deck_stats s WHERE s.guild_id = d.guild_id AND s.monster_id_1 = d.monster_id_1 AND s.monster_id_2 = d.monster_id_2 AND s.monster_id_3 = d.monster_id_3
AND ( (SELECT COUNT(*) FROM guild_siege_season WHERE end_date IS NULL) = 0 OR s.season_yyyymm >= COALESCE( #{current_season_yyyymm}, (SELECT TO_CHAR(DATE_TRUNC('month', gss.start_date), 'YYYYMM') FROM guild_siege_season gss WHERE gss.end_date IS NULL ORDER BY gss.season_no DESC LIMIT 1), '000000' ) )
) ) u ORDER BY monster_id_1, monster_id_2, monster_id_3, total_count DESC NULLS LAST, _deck_src ASC ) combined ORDER BY total_count DESC LIMIT CAST(#{paging} AS bigint) OFFSET (CAST(#{paging} AS bigint) * (CAST(#{offset} AS bigint) - 1))

/* selectTotalPageCount */ SELECT COUNT(*)::int AS rowCount FROM ( SELECT DISTINCT monster_id_1, monster_id_2, monster_id_3 FROM ( SELECT monster_id_1, monster_id_2, monster_id_3 FROM siege_defense_deck_stats WHERE 1=1
AND guild_id = #{view_guild_id}::text AND guild_id = #{sess_guild_id}::text
AND ( (SELECT COUNT(*) FROM guild_siege_season WHERE end_date IS NULL) = 0 OR season_yyyymm >= COALESCE( #{current_season_yyyymm}, (SELECT TO_CHAR(DATE_TRUNC('month', gss.start_date), 'YYYYMM') FROM guild_siege_season gss WHERE gss.end_date IS NULL ORDER BY gss.season_no DESC LIMIT 1), '000000' ) )
AND monster_id_1 IN #{id}
AND monster_id_2 IN #{id} AND monster_id_3 IN #{id}
AND (monster_id_2 IN #{id} OR monster_id_3 IN #{id})
AND (monster_id_2 IN #{id} OR monster_id_3 IN #{id})
GROUP BY monster_id_1, monster_id_2, monster_id_3
HAVING SUM(lose_count) >= #{min_lose_count}::int
UNION ALL SELECT d.monster_id_1, d.monster_id_2, d.monster_id_3 FROM siege_defense_deck_manual d WHERE 1=1
AND d.guild_id = #{view_guild_id}::text AND d.guild_id = #{sess_guild_id}::text
AND ( (SELECT COUNT(*) FROM guild_siege_season WHERE end_date IS NULL) = 0 OR d.season_yyyymm >= COALESCE( #{current_season_yyyymm}, (SELECT TO_CHAR(DATE_TRUNC('month', gss.start_date), 'YYYYMM') FROM guild_siege_season gss WHERE gss.end_date IS NULL ORDER BY gss.season_no DESC LIMIT 1), '000000' ) )
AND d.monster_id_1 IN #{id}
AND d.monster_id_2 IN #{id} AND d.monster_id_3 IN #{id}
AND (d.monster_id_2 IN #{id} OR d.monster_id_3 IN #{id})
AND (d.monster_id_2 IN #{id} OR d.monster_id_3 IN #{id})
AND 1=0
AND NOT EXISTS ( SELECT 1 FROM siege_defense_deck_stats s WHERE s.guild_id = d.guild_id AND s.monster_id_1 = d.monster_id_1 AND s.monster_id_2 = d.monster_id_2 AND s.monster_id_3 = d.monster_id_3
AND ( (SELECT COUNT(*) FROM guild_siege_season WHERE end_date IS NULL) = 0 OR s.season_yyyymm >= COALESCE( #{current_season_yyyymm}, (SELECT TO_CHAR(DATE_TRUNC('month', gss.start_date), 'YYYYMM') FROM guild_siege_season gss WHERE gss.end_date IS NULL ORDER BY gss.season_no DESC LIMIT 1), '000000' ) )
) ) u ) t

