/* insertArenaInfoBulk — rta_match (season_id 는 Java 에서 rta_season 기준 산출 후 바인딩) */
INSERT INTO public.rta_match (
	replay_id,
	season_id,
	played_at,
	winner_wizard_id,
	battle_version,
	battle_type
) VALUES

(
	#{m.rid}
	, #{m.season_id}
	, (#{m.date_add})::timestamptz
	/* winner_wizard_id: 적재 경로에서 user_list 승자 기준으로 세팅, 없으면 루트 wizard_id (구 호환) */
	, COALESCE(#{m.winner_wizard_id,jdbcType=VARCHAR}, CAST(#{m.wizard_id} AS VARCHAR))
	, #{m.battle_ver}
	, #{m.battle_type}
)

ON CONFLICT (replay_id) DO NOTHING

INSERT INTO public.rta_match_participant ( replay_id, wizard_id, season_id, played_at, wizard_name, channel_uid, team_side, country_code, rating_id, ladder_score, ladder_rank, is_winner, is_first_pick, alive_count, leader_pick_slot ) SELECT v.rid, v.wizard_id, m.season_id, m.played_at, v.wizard_name, v.channel_uid, v.team_no, v.country, r.rating_id, v.score, v.rank_no, COALESCE(v.is_winner, false), CASE WHEN v.fp IS NULL THEN NULL::boolean WHEN v.fp IN ('1','true','t','T','TRUE') THEN true WHEN v.fp IN ('0','false','f','F','FALSE') THEN false ELSE NULL::boolean END, v.alive_count, v.leader_pick_slot FROM (VALUES
( #{m.rid}::bigint , #{m.wizard_id}::varchar , #{m.wizard_name}::varchar , #{m.channel_uid}::varchar , #{m.team_no,jdbcType=SMALLINT}::smallint , #{m.country}::varchar , #{m.rating_id,jdbcType=INTEGER}::int , #{m.score,jdbcType=INTEGER}::int , #{m.rank_no,jdbcType=INTEGER}::int , #{m.is_winner,jdbcType=BOOLEAN}::boolean , #{m.is_first_pick}::text , #{m.alive_count,jdbcType=SMALLINT}::smallint , #{m.leader_pick_slot,jdbcType=SMALLINT}::smallint )
) AS v(rid, wizard_id, wizard_name, channel_uid, team_no, country, rating_id_raw, score, rank_no, is_winner, fp, alive_count, leader_pick_slot) JOIN public.rta_match m ON m.replay_id = v.rid LEFT JOIN public.rta_rating_grade r ON r.rating_id = v.rating_id_raw ON CONFLICT (replay_id, wizard_id) DO NOTHING

