/* selectRecommendedAttackDeckListCount - 추천 공덱 전체 개수 조회 */
select count(1) as total_count
  from siege_recommended_attack_deck srad
 where srad.def_monster_1 = #{dm1}
   and srad.def_monster_2 = #{dm2}
   and srad.def_monster_3 = #{dm3}

/* selectDeckDetail - 공덱 상세 정보 조회 */ SELECT srad.id as deck_id, srad.def_monster_1, srad.def_monster_2, srad.def_monster_3, srad.atk_monster_1, srad.atk_monster_2, srad.atk_monster_3, ( (SELECT COUNT(*)::int FROM siege_deck_user_vote v WHERE v.deck_id = srad.id AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND v.vote_type = 'UP') + (SELECT COUNT(*)::int FROM siege_deck_user_vote v WHERE (COALESCE(v.deck_id, 0) = 0) AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND v.vote_type = 'UP' AND ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = v.atk_monster_1::text LIMIT 1), v.atk_monster_1::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = v.atk_monster_2::text LIMIT 1), v.atk_monster_2::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = v.atk_monster_3::text LIMIT 1), v.atk_monster_3::text) ]::text[]) AS t(u) ) = ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = srad.atk_monster_1::text LIMIT 1), srad.atk_monster_1::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = srad.atk_monster_2::text LIMIT 1), srad.atk_monster_2::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = srad.atk_monster_3::text LIMIT 1), srad.atk_monster_3::text) ]::text[]) AS t(u) ) ) ) AS recommend_count, ( (SELECT COUNT(*)::int FROM siege_deck_user_vote v WHERE v.deck_id = srad.id AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND v.vote_type = 'DOWN') + (SELECT COUNT(*)::int FROM siege_deck_user_vote v WHERE (COALESCE(v.deck_id, 0) = 0) AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND v.vote_type = 'DOWN' AND ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = v.atk_monster_1::text LIMIT 1), v.atk_monster_1::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = v.atk_monster_2::text LIMIT 1), v.atk_monster_2::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = v.atk_monster_3::text LIMIT 1), v.atk_monster_3::text) ]::text[]) AS t(u) ) = ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = srad.atk_monster_1::text LIMIT 1), srad.atk_monster_1::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = srad.atk_monster_2::text LIMIT 1), srad.atk_monster_2::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = srad.atk_monster_3::text LIMIT 1), srad.atk_monster_3::text) ]::text[]) AS t(u) ) ) ) AS not_recommend_count, COALESCE( (SELECT v.vote_type FROM siege_deck_user_vote v WHERE v.deck_id = srad.id AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND #{sess_user_id} IS NOT NULL AND v.user_id = #{sess_user_id}::text LIMIT 1), (SELECT v.vote_type FROM siege_deck_user_vote v WHERE (COALESCE(v.deck_id, 0) = 0) AND v.def_monster_1 = srad.def_monster_1 AND v.def_monster_2 = srad.def_monster_2 AND v.def_monster_3 = srad.def_monster_3 AND #{sess_user_id} IS NOT NULL AND v.user_id = #{sess_user_id}::text AND ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = v.atk_monster_1::text LIMIT 1), v.atk_monster_1::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = v.atk_monster_2::text LIMIT 1), v.atk_monster_2::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = v.atk_monster_3::text LIMIT 1), v.atk_monster_3::text) ]::text[]) AS t(u) ) = ( SELECT array_agg(u ORDER BY u) FROM unnest(ARRAY[ COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = srad.atk_monster_1::text LIMIT 1), srad.atk_monster_1::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = srad.atk_monster_2::text LIMIT 1), srad.atk_monster_2::text), COALESCE((SELECT mcm.original_monster_id FROM monster_collaboration_mapping mcm WHERE mcm.collaboration_monster_id = srad.atk_monster_3::text LIMIT 1), srad.atk_monster_3::text) ]::text[]) AS t(u) ) LIMIT 1) ) AS my_vote, -- 몬스터1 정보 m1.kr_name as m1_kr_name, m1.image_url as image_url1, COALESCE(stats1.hp, 0) as m1_hp, COALESCE(stats1.atk, 0) as m1_atk, COALESCE(stats1.def, 0) as m1_def, COALESCE(stats1.spd, 0) as m1_spd, COALESCE(stats1.crit_rate, 0) as m1_crit_rate, COALESCE(stats1.crit_dmg, 0) as m1_crit_dmg, COALESCE(stats1.resistance, 0) as m1_resistance, COALESCE(stats1.accuracy, 0) as m1_accuracy, -- 몬스터2 정보 m2.kr_name as m2_kr_name, m2.image_url as image_url2, COALESCE(stats2.hp, 0) as m2_hp, COALESCE(stats2.atk, 0) as m2_atk, COALESCE(stats2.def, 0) as m2_def, COALESCE(stats2.spd, 0) as m2_spd, COALESCE(stats2.crit_rate, 0) as m2_crit_rate, COALESCE(stats2.crit_dmg, 0) as m2_crit_dmg, COALESCE(stats2.resistance, 0) as m2_resistance, COALESCE(stats2.accuracy, 0) as m2_accuracy, -- 몬스터3 정보 m3.kr_name as m3_kr_name, m3.image_url as image_url3, COALESCE(stats3.hp, 0) as m3_hp, COALESCE(stats3.atk, 0) as m3_atk, COALESCE(stats3.def, 0) as m3_def, COALESCE(stats3.spd, 0) as m3_spd, COALESCE(stats3.crit_rate, 0) as m3_crit_rate, COALESCE(stats3.crit_dmg, 0) as m3_crit_dmg, COALESCE(stats3.resistance, 0) as m3_resistance, COALESCE(stats3.accuracy, 0) as m3_accuracy FROM siege_recommended_attack_deck srad LEFT JOIN monster m1 ON srad.atk_monster_1 = m1.monster_id LEFT JOIN monster m2 ON srad.atk_monster_2 = m2.monster_id LEFT JOIN monster m3 ON srad.atk_monster_3 = m3.monster_id LEFT JOIN siege_recommended_attack_deck_stats stats1 ON srad.id = stats1.deck_id AND srad.atk_monster_1 = stats1.monster_id LEFT JOIN siege_recommended_attack_deck_stats stats2 ON srad.id = stats2.deck_id AND srad.atk_monster_2 = stats2.monster_id LEFT JOIN siege_recommended_attack_deck_stats stats3 ON srad.id = stats3.deck_id AND srad.atk_monster_3 = stats3.monster_id WHERE 1=1
AND srad.id = #{deck_id}::int
AND srad.def_monster_1 = #{def_monster_1}
AND srad.def_monster_2 = #{def_monster_2}
AND srad.def_monster_3 = #{def_monster_3}
AND srad.atk_monster_1 = #{atk_monster_1}
AND srad.atk_monster_2 = #{atk_monster_2}
AND srad.atk_monster_3 = #{atk_monster_3}
LIMIT 1

