/* insertDeckVoteRegistered - 추천 공덱에 등록된 행(deck_id) 투표 */
INSERT INTO siege_deck_user_vote (def_monster_1, def_monster_2, def_monster_3, deck_id, user_id, vote_type, atk_monster_1, atk_monster_2, atk_monster_3, crt_date, upt_date)
VALUES (#{def_monster_1}, #{def_monster_2}, #{def_monster_3}, #{deck_id}::int, #{sess_user_id}, #{vote_type}, NULL, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)

/* insertDeckVoteFree - 미등록 조합: deck_id=0 → FK가 siege_recommended_attack_deck.id=0 더미 행을 가리킴(PK에 deck_id 있으면 NULL 불가) */
INSERT INTO siege_deck_user_vote (def_monster_1, def_monster_2, def_monster_3, deck_id, user_id, vote_type, atk_monster_1, atk_monster_2, atk_monster_3, crt_date, upt_date)
VALUES (#{def_monster_1}, #{def_monster_2}, #{def_monster_3}, 0, #{sess_user_id}, #{vote_type}, #{atk_monster_1}, #{atk_monster_2}, #{atk_monster_3}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)

mapper.delete:
/* deleteDeckVote - 추천/비추천 취소: deck_id 있으면 등록 행, 없으면 atk로 자유 투표 행 */
DELETE FROM siege_deck_user_vote
 WHERE user_id = #{sess_user_id}
   AND def_monster_1 = #{def_monster_1}
   AND def_monster_2 = #{def_monster_2}
   AND def_monster_3 = #{def_monster_3}


   AND deck_id = #{deck_id}::int


   AND COALESCE(deck_id, 0) = 0
   AND atk_monster_1 = #{atk_monster_1}
   AND atk_monster_2 = #{atk_monster_2}
   AND atk_monster_3 = #{atk_monster_3}

/* deleteDeckDetail - 공덱 삭제 */
delete
from siege_recommended_attack_deck
where 1=1

	and id = #{deck_id}::int


	and atk_monster_1 = #{atk_monster_1}


	and atk_monster_2 = #{atk_monster_2}


	and atk_monster_3 = #{atk_monster_3}

/* deleteGuildSiegeBattleDeckByMatchId - match_id 기준으로 battle_deck 삭제 */
DELETE FROM view_battle_deck_info
WHERE match_id = #{matchId}

/* deleteGuildSiegeBattleLogByMatchId - match_id 기준으로 battle_log 삭제 */
DELETE FROM battle_log_list
WHERE match_id = #{matchId}

/* deleteGuildSiegeInfoByMatchId - match_id 기준으로 guild_info 삭제 */
DELETE FROM guild_siege_battle_log
WHERE match_id = #{matchId}
